/**
 * LeadImportService
 *
 * Bulk-safe lead import used by the trade-show screen. A single DML statement is
 * issued per call, partial successes are preserved, and per-row errors are reported
 * back by input index. Duplicate e-mails *within a single call* are filtered in
 * memory (case-insensitive, whitespace-trimmed) and never reach the database.
 *
 * Sharing is enforced so the running user's rules apply to every operation.
 */
public with sharing class LeadImportService {

    /**
     * Result wrapper returned to the caller (the custom screen). Members are
     * never null so callers can iterate / read them without null checks.
     */
    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }

    /**
     * Imports the supplied leads.
     *
     * @param leads  leads to import (may be null / empty)
     * @return ImportResult with counts, inserted Ids (input order) and per-index errors
     */
    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        // Contract: null / empty input -> zero success, empty collections, no exception.
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Set<String> seenEmails = new Set<String>();
        List<Lead> recordsToInsert = new List<Lead>();
        // Parallel list mapping SaveResult index -> original 0-based input index.
        List<Integer> originalIndices = new List<Integer>();

        // ---- Pre-processing pass: LeadSource default + in-call duplicate detection ----
        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            // Normalize the e-mail for duplicate detection. Leads with no e-mail
            // (null / blank) are never considered duplicates.
            String normalizedEmail = null;
            if (lead.Email != null && !String.isBlank(lead.Email)) {
                normalizedEmail = lead.Email.trim().toLowerCase();
            }

            if (normalizedEmail != null && seenEmails.contains(normalizedEmail)) {
                // Subsequent occurrence of an already-seen e-mail in this call:
                // report and skip, even if the first occurrence later fails to insert.
                result.errorsByIndex.put(
                    i,
                    'Duplicate email in import: ' + normalizedEmail
                );
                continue;
            }

            if (normalizedEmail != null) {
                seenEmails.add(normalizedEmail);
            }

            // Default the lead source before it is sent to the database.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            recordsToInsert.add(lead);
            originalIndices.add(i);
        }

        // ---- Single DML statement, partial-success mode (allOrNone = false) ----
        // Using Database.insert(..., false) ensures that valid records are inserted
        // even when others are rejected and that the method does not throw because
        // some leads are invalid.
        if (!recordsToInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(recordsToInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Integer originalIndex = originalIndices[j];

                if (saveResults[j].isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(saveResults[j].getId());
                } else {
                    // Build a single message from all database errors for this record.
                    List<String> messages = new List<String>();
                    for (Database.Error err : saveResults[j].getErrors()) {
                        messages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
                }
            }
        }

        return result;
    }
}
