public with sharing class ShipmentEventPublisher {

    public class Shipment {
        public String orderNumber;
        public String trackingNumber;
        public String carrier;

        public Shipment(String orderNumber, String trackingNumber, String carrier) {
            this.orderNumber = orderNumber;
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }

    public static Integer publishShipments(List<Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> events = new List<FB_Shipment_Event__e>();
        for (Shipment s : shipments) {
            if (String.isBlank(s.orderNumber)) {
                continue;
            }
            FB_Shipment_Event__e evt = new FB_Shipment_Event__e();
            evt.Order_Number__c = s.orderNumber;
            evt.Tracking_Number__c = s.trackingNumber;
            evt.Carrier__c = s.carrier;
            events.add(evt);
        }

        if (events.isEmpty()) {
            return 0;
        }

        Database.SaveResult[] results = EventBus.publish(events);

        Integer count = 0;
        for (Database.SaveResult r : results) {
            if (r.isSuccess()) {
                count++;
            }
        }
        return count;
    }
}
