public with sharing class Application {

    public static fflib_Application.UnitOfWorkFactory UnitOfWork { get; set; }
    public static fflib_Application.ServiceFactory Service { get; set; }
    public static fflib_Application.SelectorFactory Selector { get; set; }
    public static fflib_Application.DomainFactory Domain { get; set; }

    static {
        // Unit of Work: Account, Contact, Opportunity and OpportunityContactRole.
        // Registering all four types in one UnitOfWorkFactory lets a single commit
        // insert Accounts, their Contacts, their Opportunities and the
        // OpportunityContactRoles that link the new Opportunities and Contacts,
        // with the inter-record relationships tracked through the unit of work.
        UnitOfWork = new fflib_Application.UnitOfWorkFactory(
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType                => Account.class,
                Contact.SObjectType                => Contact.class,
                Opportunity.SObjectType            => Opportunity.class,
                OpportunityContactRole.SObjectType => OpportunityContactRole.class
            }
        );

        // Service layer: IAccountsService is implemented by AccountsServiceImpl.
        Service = new fflib_Application.ServiceFactory(
            new Map<Type, Type>{
                IAccountsService.class => AccountsServiceImpl.class
            }
        );

        // Selector layer: Account records are read by AccountsSelector,
        // Contact records by ContactsSelector.
        Selector = new fflib_Application.SelectorFactory(
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => AccountsSelector.class,
                Contact.SObjectType => ContactsSelector.class
            }
        );

        // Domain layer: Account records are wrapped by the Accounts domain.
        // Domain.newInstance(Set<Id>) resolves the SObjectType from the ids and
        // queries the records via the Selector factory above, then wraps them.
        Domain = new fflib_Application.DomainFactory(
            new Map<Schema.SObjectType, fflib_SObjectDomain.IConstructable>{
                Account.SObjectType => new Accounts.Constructor()
            }
        );
    }
}
