public without sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = (List<Opportunity>) OpportunitiesSelector.newInstance()
            .selectById(opportunityIds);

        List<Opportunity> toUpdate = new List<Opportunity>();
        List<Deal_Won__e> eventsToPublish = new List<Deal_Won__e>();
        Date today = Date.today();

        for (Opportunity opp : opps) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }
            opp.StageName = 'Closed Won';
            opp.CloseDate = today;
            toUpdate.add(opp);

            Deal_Won__e evt = new Deal_Won__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Amount__c = opp.Amount;
            eventsToPublish.add(evt);
        }

        if (toUpdate.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.registerDirty(toUpdate);

        if (!eventsToPublish.isEmpty()) {
            uow.registerWorkItem(new PublishDealWonWorkItem(eventsToPublish));
        }

        uow.commit();

        return toUpdate.size();
    }

    private class PublishDealWonWorkItem implements fflib_IUnitOfWorkWorkItem {
        private final List<Deal_Won__e> events;

        PublishDealWonWorkItem(List<Deal_Won__e> events) {
            this.events = events;
        }

        public void execute() {
            EventBus.publish(events);
        }
    }
