```apex
/**
 * ErpCustomerSync
 *
 * Queueable that POSTS one HTTP request per Account to the ERP.
 * Chaining is used when more than 100 accounts are queued (async
 * callout ceiling per execution is 100).
 *
 * Endpoint : POST callout:ERP/api/customers
 * Body     : [{"salesforceId":"001…","name":"…","country":"…"}]
 * Response : 202 Accepted (error handling / retries out of scope)
 */
public with sharing class ErpCustomerSync implements Queueable {

    private static final String   ENDPOINT      = 'callout:ERP/api/customers';
    private static final Integer  MAX_CALLOUTS  = 100;

    /* Inner DTO – keeps the Queueable payload small (no full sObjects). */
    public class AccountDto {
        public Id     sfId;
        public String name;
        public String country;

        public AccountDto(Id sfId, String name, String country) {
            this.sfId   = sfId;
            this.name   = name;
            this.country = country;
        }
    }

    /* ------------------------------------------------------------------ */
    //  Instance state
    /* ------------------------------------------------------------------ */
    private final List<AccountDto> accounts;
    private final Integer          nextIndex;

    /* ------------------------------------------------------------------ */
    //  Constructor
    /* ------------------------------------------------------------------ */
    public ErpCustomerSync(List<AccountDto> accounts, Integer nextIndex) {
        this.accounts  = accounts;
        this.nextIndex = nextIndex;
    }

    /* ------------------------------------------------------------------ */
    //  Public entry point – called from the trigger
    /* ------------------------------------------------------------------ */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<AccountDto> dtos = new List<AccountDto>();
        for (Account acc : newAccounts) {
            String country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
            dtos.add(new AccountDto(acc.Id, acc.Name, country));
        }

        System.enqueueJob(new ErpCustomerSync(dtos, 0));
    }

    /* ------------------------------------------------------------------ */
    //  Queueable.execute
    /* ------------------------------------------------------------------ */
    public void execute(QueueableContext context) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        Integer stopIndex = Math.min(nextIndex + MAX_CALLOUTS, accounts.size());

        for (Integer i = nextIndex; i < stopIndex; i++) {
            AccountDto dto = accounts[i];

            HttpRequest req = new HttpRequest();
            req.setMethod('POST');
            req.setEndpoint(ENDPOINT);
            req.setHeader('Content-Type', 'application/json');

            List<Object> payload = new List<Object>{
                new Map<String, Object>{
                    'salesforceId' => dto.sfId,
                    'name'         => dto.name,
                    'country'      => dto.country
                }
            };
            req.setBody(JSON.serialize(payload));

            Http       http  = new Http();
            HttpResponse resp = http.send(req);

            // 202 Accepted expected. Error handling / retries are out of
            // scope – but log a warning for observability.
            if (resp.getStatusCode() < 200 || resp.getStatusCode() >= 300) {
                System.debug(LoggingLevel.WARN,
                    'ErpCustomerSync: unexpected status ' + resp.getStatusCode()
                    + ' for Account ' + dto.sfId);
            }
        }

        // Chain when more accounts remain.
        if (stopIndex < accounts.size()) {
            System.enqueueJob(new ErpCustomerSync(accounts, stopIndex));
        }
    }
}
