public class FollowUpTaskService {
    /**
     * Creates a follow-up Task for each Opportunity provided.
     * Individual inserts are wrapped in try/catch so that a validation-rule
     * rejection on one Task does not prevent the remaining Tasks from being
     * created.
     *
     * @param  opportunityIds  list of Opportunity Ids that came out of the
     *                          weekly pipeline review.
     * @return Set<Id>          Opportunity Ids whose Task could NOT be created.
     *                          Empty set when every Task succeeded.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOppIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOppIds;
        }

        // Single SOQL to retrieve Name and OwnerId – avoids a query inside the loop.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM   Opportunity
            WHERE  Id IN :opportunityIds
        ];

        // Straightforward per-record approach as requested:
        // one insert inside try/catch so a DML/VR exception only
        // affects the current record.
        for (Opportunity opp : opportunities) {
            Task followUpTask = new Task();
            followUpTask.WhatId       = opp.Id;
            followUpTask.OwnerId      = opp.OwnerId;
            followUpTask.Subject      = 'Follow up: ' + opp.Name;
            followUpTask.ActivityDate = Date.today().addDays(7);
            followUpTask.Status       = 'Not Started';
            followUpTask.Priority     = 'Normal';

            try {
                insert followUpTask;
            } catch (Exception ex) {
                // Validation rule, required-field, or other DML error.
                // Log so the ops team can investigate.
                System.debug(LoggingLevel.ERROR,
                    'FollowUpTaskService: failed to create Task for Opportunity ' +
                    opp.Id + ' – ' + ex.getMessage());

                failedOppIds.add(opp.Id);
            }
        }

        return failedOppIds;
    }
}
```

