            for (Opportunity opp : Trigger.new) {
                Opportunity old = Trigger.oldMap.get(opp.Id);
                if (opp.AccountId != null
                    && (opp.StageName != old.StageName || opp.Amount != old.Amount)) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
    }

