```apex
/**
 * Applies the standard product discount to new OpportunityLineItems
 * when the rep has not entered a Discount value.
 *
 * Delegates all discount logic to PricingRules (owned by the pricing team).
 * We call PricingRules.standardDiscountForFamily() rather than
 * standardDiscountFor() in a loop, because the latter issues one SOQL
 * per product and would blow the governor limit on a 200-line CPQ quote.
 * standardDiscountForFamily is a public method on PricingRules, so every
 * discount rule still lives in exactly one place.
 */
public with sharing class LineItemDiscountHandler {

    /**
     * Called from the before-insert trigger.
     * For every new line whose Discount is null, populates the
     * standard discount from PricingRules.
     *
     * @param newLines  Trigger.new records
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        // Collect the Product2Id values that actually need a discount.
        Set<Id> neededProductIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null) {
                neededProductIds.add(line.Product2Id);
            }
        }

        if (neededProductIds.isEmpty()) {
            return;
        }

        // Single SOQL to resolve products and their families.
        Map<Id, Product2> productsById = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :neededProductIds]
        );

        // Build a product → standardDiscount map by delegating to PricingRules.
        // We call standardDiscountForFamily (the pricing team's public API)
        // so no rule logic is duplicated here.
        Map<Id, Decimal> discountByProduct = new Map<Id, Decimal>();
        for (Product2 p : productsById.values()) {
            discountByProduct.put(p.Id, PricingRules.standardDiscountForFamily(p.Family));
        }

        // Assign discounts to lines that need them.
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null) {
                line.Discount = discountByProduct.get(line.Product2Id);
            }
        }
    }
}
