```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_CHARS = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error = null;

    /** @type {number|null} */
    _debounceTimer = null;

    /** Monotonically increasing counter used to ignore stale responses */
    _requestId = 0;

    /** Set true in disconnectedCallback to discard in-flight work */
    _destroyed = false;

    // ---------------------------------------------------------------
    // Public template binding
    // ---------------------------------------------------------------
    get hasResults() {
        return this.contacts.length > 0;
    }

    // ---------------------------------------------------------------
    // Event handlers
    // ---------------------------------------------------------------
    handleSearch(event) {
        const raw = event.target.value;
        const searchTerm = raw ? raw.trim() : '';

        // Cancel any pending debounce timer (no Apex call yet)
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }

        // Not enough characters → clear everything, no call
        if (searchTerm.length < MIN_CHARS) {
            this.contacts = [];
            this.error = null;
            // Invalidate any in-flight response that might still land
            this._requestId++;
            return;
        }

        // Schedule the search after the debounce window
        const capturedTerm = searchTerm;

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;

            if (this._destroyed) return;

            const myId = ++this._requestId;

            searchContacts({ searchTerm: capturedTerm })
                .then(result => {
                    // Ignore if component is gone or a newer request exists
                    if (this._destroyed || myId !== this._requestId) return;
                    this.contacts = result || [];
                    this.error = null;
                })
                .catch(err => {
                    if (this._destroyed || myId !== this._requestId) return;
                    this.contacts = [];
                    this.error = (err && err.body && err.body.message)
                        ? err.body.message
                        : 'An unknown error occurred.';
                });
        }, DEBOUNCE_MS);
    }

    // ---------------------------------------------------------------
    // Lifecycle
    // ---------------------------------------------------------------
    disconnectedCallback() {
        this._destroyed = true;
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
    }
}
