import { LightningElement, api } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { updateRecord } from 'lightning/uiRecordApi';
import getContacts from '@salesforce/apex/ContactController.getContacts';

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts;

    columns = [
        { label: 'Name', fieldName: 'Name', type: 'text' },
        { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
        { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
        { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
    ];

    draftValues = [];

    get contacts() {
        return (this.wiredContacts && this.wiredContacts.data) || [];
    }

    async handleSave(event) {
        const drafts = (event.detail && event.detail.draftRows) || [];

        if (drafts.length === 0) {
            return;
        }

        const savePromises = drafts.map(async (draft) =>
            updateRecord({
                fields: { ...draft }
            })
        );

        const results = await Promise.allSettled(savePromises);
        const failure = results.find((result) => result.status === 'rejected');

        if (failure) {
            const reason = failure.reason;
            const message = reason && reason.body ? reason.body.message : undefined;

            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Could not save contacts',
                    message
                })
            );
            return;
        }

        this.dispatchEvent(
            new ShowToastEvent({
                variant: 'success',
                title: 'Contacts updated'
            })
        );

        this.draftValues = [];

        if (this.wiredContacts) {
            await Promise.resolve(refreshApex(this.wiredContacts)).catch(() => {});
        }
    }
}
