import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE
} from 'c/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    recordId;
    subscription = null;

    @wire(MessageContext)
    messageContext;

    connectedCallback() {
        this.subscribeToChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromChannel();
    }

    subscribeToChannel() {
        // Never hold more than one subscription.
        if (this.subscription) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => {
                this.handleMessage(message);
            },
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromChannel() {
        unsubscribe(this.subscription);
        this.subscription = null;
    }

    handleMessage(message) {
        if (message && message.recordId) {
            this.recordId = message.recordId;
        } else {
            this.recordId = undefined;
        }
    }

    handleClear(event) {
        if (event.currentTarget.dataset.action === 'clear') {
            publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
        }
    }
}
