     * are callable, and the order matches the for:each rendering order.
     */
    get editors() {
        return Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );
    }

    handleReset() {
        this.editors.forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.editors;
        let allValid = true;

        // Validate every editor, regardless of earlier failures, so that all
        // invalid lines surface their errors at once.
        for (const editor of editors) {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        }

        if (allValid) {
            const values = editors.map((editor) => editor.getValue());
            this.showError = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: values }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
