import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL = 60000;

export default class QueueMonitor extends LightningElement {
    @track waiting = undefined;
    @track longestWaitMinutes = undefined;
    @track errorMessage = null;

    _inFlight = false;
    _intervalId = null;
    _boundVisibilityHandler = null;

    connectedCallback() {
        this._boundVisibilityHandler = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._boundVisibilityHandler);
        this.loadStats();
        this.startPolling();
    }

    disconnectedCallback() {
        this.stopPolling();
        if (this._boundVisibilityHandler) {
            document.removeEventListener('visibilitychange', this._boundVisibilityHandler);
            this._boundVisibilityHandler = null;
        }
        this._inFlight = false;
    }

    startPolling() {
        this.stopPolling();
        this._intervalId = setInterval(() => {
            if (document.visibilityState === 'visible') {
                this.loadStats();
            }
        }, POLL_INTERVAL);
    }

    stopPolling() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else if (document.visibilityState === 'visible') {
            this.loadStats();
            this.startPolling();
        }
    }

    loadStats() {
        if (this._inFlight) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }
        this._inFlight = true;
        getQueueStats()
            .then((stats) => {
                this.waiting = stats.waiting;
                this.longestWaitMinutes = stats.longestWaitMinutes;
                this.errorMessage = null;
            })
            .catch((error) => {
                this.errorMessage = (error.body && error.body.message) || 'An error occurred';
            })
            .finally(() => {
                this._inFlight = false;
            });
    }

    get hasStats() {
        return this.waiting !== undefined && this.longestWaitMinutes !== undefined;
    }
}
