import { LightningElement, api } from 'lwc';

let idCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeIndex = 0;

    // Unique prefix for this component instance
    _uid = `slb-${Math.random().toString(36).substring(2, 9)}`;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = value || [];
        this._activeIndex = 0;
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        if (newValue === this._value) return;
        this._value = newValue;
        this._syncActiveIndex();
    }

    connectedCallback() {
        this._syncActiveIndex();
    }

    _syncActiveIndex() {
        if (this._value) {
            const idx = this._options.findIndex(o => o.value === this._value);
            this._activeIndex = idx >= 0 ? idx : 0;
        } else {
            this._activeIndex = 0;
        }
    }

    get activeId() {
        return `slb-${this._uid}-opt-${this._activeIndex}`;
    }

    get computedOptions() {
        return (this._options || []).map((opt, index) => ({
            value: opt.value,
            label: opt.label,
            id: `slb-${this._uid}-opt-${index}`,
            isSelected: opt.value === this._value
        }));
    }

    handleKeyDown(event) {
        const key = event.key;
        if (key === 'ArrowDown' || key === 'ArrowUp' || key === 'Home' || key === 'End' || key === 'Enter' || key === ' ') {
            event.preventDefault();
            switch (key) {
                case 'ArrowDown':
                    this._moveActive(1);
                    break;
                case 'ArrowUp':
                    this._moveActive(-1);
                    break;
                case 'Home':
                    this._setActiveIndex(0);
                    break;
                case 'End':
                    this._setActiveIndex(this._options.length - 1);
                    break;
                case 'Enter':
                case ' ':
                    this._selectActive();
                    break;
                default:
                    break;
            }
        }
    }

    handleClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        if (!isNaN(index)) {
            this._setActiveIndex(index);
            this._selectActive();
        }
    }

    _moveActive(delta) {
        const nextIndex = this._activeIndex + delta;
        if (nextIndex >= 0 && nextIndex < this._options.length) {
            this._activeIndex = nextIndex;
        }
    }

    _setActiveIndex(index) {
        if (index >= 0 && index < this._options.length) {
            this._activeIndex = index;
        }
    }

    _selectActive() {
        const option = this._options[this._activeIndex];
        if (!option) return;

        if (option.value !== this._value) {
            this._value = option.value;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: option.value },
                bubbles: true,
                composed: true
            }));
        }
    }
}
