public class FamilyService {

    /**
     * Creates parent-child relationships in NPSP so that:
     *  - the child's relationships show the parent as "Parent" (Status Current)
     *  - the parent's relationships show the child as the reciprocal type
     *    (Son / Daughter / Child) determined by NPSP's List-Setting reciprocal lookup.
     *
     * NPSP's relationship trigger (List Setting mode) automatically creates and links
     * the reciprocal record, so we insert only the forward (child → parent) records.
     *
     * Idempotent: any pair that already has a relationship in either direction is skipped.
     *
     * SOQL/DML budget for ≤ 200 pairs: 1 query, 1 DML.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every distinct contact involved in the import
        Set<Id> allContactIds = new Set<Id>();
        allContactIds.addAll(parentIdByChildId.keySet());
        allContactIds.addAll(parentIdByChildId.values());

        // ── Single SOQL query ──────────────────────────────────────────────
        // Find every existing relationship that touches any of our contacts.
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c,
                   npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
               OR npe4__RelatedContact__c IN :allContactIds
        ];

        // Build an unordered-pair set so "A→B" and "B→A" are treated as the same
        Set<String> takenPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            Id c  = rel.npe4__Contact__c;
            Id rc = rel.npe4__RelatedContact__c;
            if (c != null && rc != null) {
                takenPairs.add(pairKey(c, rc));
            }
        }

        // ── Build the new forward (child → parent) records ────────────────
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) {
                continue;
            }

            String key = pairKey(childId, parentId);

            // Skip if a relationship already exists (either direction)
            if (takenPairs.contains(key)) {
                continue;
            }
            // Guard against accidental intra-batch duplicates (map prevents this,
            // but be defensive)
            takenPairs.add(key);

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = 'Parent',
                npe4__Status__c         = 'Current'
            ));
        }

        // ── Single DML statement ───────────────────────────────────────────
        // NPSP's Relationship trigger (List Setting mode) will automatically
        // create the reciprocal record for each insert and populate
        // npe4__ReciprocalRelationship__c on both sides, selecting the
        // reciprocal Type via the npe4__Relationship_Lookup__c configuration
        // (Male → "Son", Female → "Daughter", Neutral → "Child").
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    // ── helpers ────────────────────────────────────────────────────────────

    /** Canonical key for an unordered pair of Ids. */
    private static String pairKey(Id id1, Id id2) {
        // String comparison ensures a stable order regardless of record-type prefix
        return id1 < id2
            ? String.valueOf(id1) + ':' + String.valueOf(id2)
            : String.valueOf(id2) + ':' + String.valueOf(id1);
    }
}
