```apex
public with sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    // Accumulates Opportunity Ids that need ERP sync across all chunks of the
    // current DML operation. Cleared by OpportunityErpSyncFinalizer once enqueued.
    // Statics persist across the internal chunks of a single DML statement, so all
    // 250 records of a chunked insert land here before the finalizer runs.
    public static Set<Id> opportunityIdsForSync = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        if (opportunityIdsForSync == null) {
            opportunityIdsForSync = new Set<Id>();
        }
        for (SObject s : triggerNew) {
            opportunityIdsForSync.add(s.Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (opportunityIdsForSync == null) {
            opportunityIdsForSync = new Set<Id>();
        }
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        for (SObject s : triggerNew) {
            SObject oldRec = oldMap.get(s.Id);
            if (oldRec != null && oldRec.get('StageName') != s.get('StageName')) {
                opportunityIdsForSync.add(s.Id);
            }
        }
    }
}
