File: force-app/main/default/classes/OpportunityErpSyncFinalizer.cls
```apex
// Registered via DML_Finalizer__mdt. TAF runs this at the end of EVERY DML operation
// it handles, for any sObject, so it must be safe to call when nothing is collected
// and must not perform DML. It enqueues at most one Queueable per DML operation.
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        Set<Id> ids = TA_Opportunity_CollectForErpSync.opportunityIdsForSync;
        if (ids != null && !ids.isEmpty()) {
            // Copy before clearing so the finalizer is idempotent if it were to run again.
            Set<Id> toSync = new Set<Id>(ids);
            ids.clear();
            System.enqueueJob(new OpportunityErpSyncJob(toSync));
        }
    }
}
